func (v CrsValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var crsType basetypes.ObjectValue

	if v.CrsType.IsNull() {
		crsType = types.ObjectNull(
			CrsTypeValue{}.AttributeTypes(ctx),
		)
	}

	if v.CrsType.IsUnknown() {
		crsType = types.ObjectUnknown(
			CrsTypeValue{}.AttributeTypes(ctx),
		)
	}

	if !v.CrsType.IsNull() && !v.CrsType.IsUnknown() {
		crsType = types.ObjectValueMust(
			CrsTypeValue{}.AttributeTypes(ctx),
			v.CrsType.Attributes(),
		)
	}

	var prior basetypes.ObjectValue

	if v.Prior.IsNull() {
		prior = types.ObjectNull(
			PriorValue{}.AttributeTypes(ctx),
		)
	}

	if v.Prior.IsUnknown() {
		prior = types.ObjectUnknown(
			PriorValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Prior.IsNull() && !v.Prior.IsUnknown() {
		prior = types.ObjectValueMust(
			PriorValue{}.AttributeTypes(ctx),
			v.Prior.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"type": basetypes.ObjectType{
			AttrTypes: CrsTypeValue{}.AttributeTypes(ctx),
		},
		"prior": basetypes.ObjectType{
			AttrTypes: PriorValue{}.AttributeTypes(ctx),
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"type":  crsType,
			"prior": prior,
		})

	return objVal, diags
}

func (v CrsValue) Equal(o attr.Value) bool {
	other, ok := o.(CrsValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.CrsType.Equal(other.CrsType) {
		return false
	}

	if !v.Prior.Equal(other.Prior) {
		return false
	}

	return true
}

